using namespace std;

int main()
{
    int xa,ya,xb,yb;
    cin >> xa >> ya >> xb >> yb;

    int x_min = min(xa,xb);
    int x_max = max(xa,xb);
    int y_min = min(ya,yb);
    int y_max = max(ya,yb);

    int n;
    cin >> n;

    map<pair<int,int>,bool> seats;

    int x_dist,y_dist;
    int x,y,r;
    for (int i = 0; i < n; i++) {
        cin >> x >> y >> r;

        //Left side
        x_dist = x - x_min;
        if (r >= abs(x_dist)) {
            y_dist = (int) sqrt((double) r*r - x_dist*x_dist);
            for (int j = max(y_min,y-y_dist); j <= min(y+y_dist,y_max); j++)
                if (!seats.count(make_pair(x_min,j)))
                    seats[make_pair(x_min,j)] = true;
        }

        //Right side
        x_dist = x - x_max;
        if (r >= abs(x_dist)) {
            y_dist = (int) sqrt((double) r*r - x_dist*x_dist);
            for (int j = max(y_min,y-y_dist); j <= min(y+y_dist,y_max); j++)
                if (!seats.count(make_pair(x_max,j)))
                    seats[make_pair(x_max,j)] = true;
        }

        //Bottom side
        y_dist = y - y_min;
        if (r >= abs(y_dist)) {
            x_dist = (int) sqrt((double) r*r - y_dist*y_dist);
            for (int j = max(x_min,x-x_dist); j <= min(x+x_dist,x_max); j++)
                if (!seats.count(make_pair(j,y_min)))
                    seats[make_pair(j,y_min)] = true;
        }

        //Top side
        y_dist = y - y_max;
        if (r >= abs(y_dist)) {
            x_dist = (int) sqrt((double) r*r - y_dist*y_dist);
            for (int j = max(x_min,x-x_dist); j <= min(x+x_dist,x_max); j++)
                if (!seats.count(make_pair(j,y_max)))
                    seats[make_pair(j,y_max)] = true;
        }
    }

    cout << 2*(x_max - x_min + y_max - y_min) - seats.size() << endl;
}

