    int n;
    std::cin >> n;

    std::vector<int> a(n), b(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }
    for (int i = 0; i < n; i++) {
        std::cin >> b[i];
    }
    std::vector<int> p(n);
    std::iota(p.begin(), p.end(), 0);
    std::sort(p.begin(), p.end(),
        [&](int i, int j) {
            return a[i] + b[i] > a[j] + b[j];
        });
    i64 ans = 0;
    for (int i = 0; i < n; i++) {
        int j = p[i];
        if (i % 2 == 0) {
            ans += a[j] - 1;
        } else {
            ans -= b[j] - 1;
        }
    }
    std::cout << ans << "\n";
}

