template <typename T> void fastInt(T &angka){
    T kali = 1; angka = 0; char input = gc();
    while(!isdigit(input)){if(input == '-') kali = -1; input = gc();}
    while(isdigit(input)) angka = (angka << 3) + (angka << 1) + input - 48, input = gc();
    angka *= kali;
}

void fastStr(string &str){
