ll powMod(ll x, ll y, ll p){
    ll res = 1;
    x = x % p;
    if (x == 0) return 0;

    while (y > 0){
        if (y & 1) res = ((res % p) * (x % p)) % p;
        y = y >> 1;
        x = ((x % p) * (x % p)) % p;
    }
    return res;
}

void solve(){
    ll n, m, maxi = LLONG_MIN, mini = LLONG_MAX, sum = 0;
    fastInt(n);
    fastInt(m);
    for(ll i = 1; i <= n; ++i){
        ll __right = ((n - i) * (n - i + 1)) / 2;
        ll __left = ((i - 1) * i) / 2;
        maxi = max(maxi, __right + __left);
        mini = min(mini, __right + __left);
    }
    for(ll i = 0; i < m; ++i){
        ll x, d;
        fastInt(x);
        fastInt(d);
        ll ifMax = (n * x) + (d * maxi);
        ll ifMin = (n * x) + (d * mini);
        sum += max(ifMax, ifMin);
    }
    double ans = ((sum * 1.0) / (n * 1.0));
    cout << fixed << ans << '\n';
}

