int binary_s(int a[],int l,int h,int k)
{
    if (l <= h)
    {
        int mid = (l + h) / 2;
        if (k == a[mid])
            return mid;
        if (k < a[mid])
        {

            return binary_s(a, l, mid - 1, k);
        }
        else
            return binary_s(a, mid + 1, h, k);
    }
    else
        return -1;
}

