vl A;

ll mexBetween(int l, int r){
	if (l > r) return 0;
	assert(0 <= l && l <= r && r < SIZE(A));
	return (r-l+1)*(r-l+1);
}

ll dp(int i, vl &memo, map<int, int> &nextMove){
	if (i == -1) return 0;

	if (memo[i] == UNDEFINED){
		memo[i] = A[i];
		for(int j = -1; j < i; j++){
			ll currentOption = A[i] + dp(j, memo, nextMove) + mexBetween(j+1, i-1);
			if (currentOption >= memo[i]) nextMove[i] = j;
			memo[i] = max(memo[i], currentOption);
		}
	}

	return memo[i];
}

void agregarA(vector<ii> & intervalos, int l, int r){
	if (l <= r && l >= 0 && r < SIZE(A)) intervalos.pb({l, r});
}

void segundaPasada(vector<ii> &operaciones, int l, int r){
	if (l > r) return ;

	segundaPasada(operaciones, l, r-1);
	operaciones.pb({l, r});
	segundaPasada(operaciones, l, r-1);
}

void primeraPasada(vector<ii> &operaciones, int l, int r){
	if (l > r) return ;

	primeraPasada(operaciones, l, r-1);
	if (A[r] == (r-l)) return ;
	operaciones.pb({l, r});
	segundaPasada(operaciones, l, r-1);
}

void solve(){
	int n; cin >> n;
	A.resize(n); forn(i, n) cin >> A[i];

	vl memo(n, UNDEFINED);
	map<int, int> nextMove;

	ll res = n*n; // No dejaste fijo a ninguno
	int empieza = UNDEFINED;

	dforn(i, n){ // El primero a la derecha que fijas es el i
		ll currentRes = dp(i, memo, nextMove) + mexBetween(i+1, n-1);
		if (currentRes > res) empieza = i;
		res = max(res, currentRes);
	}

	int end = n-1;

	vector<ii> intervalos;
	// El primer intervalo es [empieza+1, end]
	agregarA(intervalos, empieza+1, end);
	//~ DBG(empieza);
	while (empieza != UNDEFINED){
		end = empieza-1;
		empieza = nextMove[empieza];
		agregarA(intervalos, empieza+1, end);
		//~ DBG(empieza);
	}

	//~ DBG(intervalos);

	vector<ii> operaciones;
	for (auto [l, r] : intervalos) { 
		primeraPasada(operaciones, l, r);
		operaciones.pb({l, r});
	}

	cout << res << " " << SIZE(operaciones) << "\n";
	for (auto [l, r] : operaciones) cout << l+1 << " " << r+1 << "\n";
}


