typedef long long LL;
const int N = 1e5+5, DIGIT = 40;
LL a[N], pre[N], r[N];
int seg[4*N][5], m=1, n;

void build(int x, int dig, int L, int R) {
	seg[x][0] = L; seg[x][1] = R;
	seg[x][2] = seg[x][3] = -1;
	seg[x][4] = 0;
	if (L == R) return;
	while(dig>0 && (r[L]>>dig)==(r[R]>>dig)) --dig;
	int ll=L,rr=R,mm,M=L;
	while(ll<=rr) {
		mm=(ll+rr)/2;
		if((r[mm]>>dig)==(r[L]>>dig)) {M=mm;ll=mm+1;}
		else rr=mm-1;
	}
	seg[x][4] = dig;
	seg[x][2] = m++;
	seg[x][3] = m++;
	build(seg[x][2], dig, L, M);
	build(seg[x][3], dig, M+1, R);
}

LL ask(LL value) {
	int x = 0; LL ret = 0;
	while(1) {
		if(seg[x][0] == seg[x][1]) { ret = r[seg[x][0]]^value; break; }
		int D = seg[x][4];
		int dir = ((value >> D)&1);
		if(dir) x = seg[x][2]; else x = seg[x][3];
	}
	return ret;
}

