    std::vector<uint32_t> as(n);
    for (int i = 0; i < n; i++) {
        in >> as[i];
    }
    std::sort(as.begin(), as.end());
    uint32_t cur = 2 * k;
    int res = 0;
    for (uint32_t v : as) {
        while (v > cur) {
            res++;
            cur = cur * 2;
        }
        cur = std::max(cur, 2 * v);
    }
    out << res << std::endl;
}

