using namespace std;
typedef long long ll;
const int N = 2e5 + 10;
int a[N];
void solve() {
	int n;
	cin >> n;
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
	}
	vector<map <pair<int, int>, int>> mp(3);
	map <pair<int, pair<int, int>>, int> yp;
	for (int i = 1; i <= n - 2; i++) {
		mp[0][{ a[i], a[i + 1] }]++;
		mp[1][{ a[i], a[i + 2] }]++;
		mp[2][{ a[i + 1], a[i + 2] }]++;
		yp[{a[i], { a[i + 1], a[i + 2] }}]++;
	}
	ll ans = 0;
	for (auto w : mp) {
		for (auto it : w) {
			ans = (ans + (it.second * 1ll * (it.second - 1)) / 2);
		}
	}
	ll w = 0;
	for (auto it : yp) {
		w = (w + (it.second * 1ll * (it.second - 1)) / 2);
	}
	ans -= 3 * w;
	cout << ans << "\n";
} 
int main() {
	int t;
	cin >> t;
	while (t--) {
		solve();
	}
}

