	}
	while(q--)
	{
		ll x;
		scanf("%lld", &x);
		x--;
		if (x<=2*n)
		{
			wyp(ans[x]);
		}
		else
		{
			x-=n;
			x%=(n-1);
			x+=n;
			wyp(ans[x]);
		}
	}
	return 0;
}

