const int MaxN = 1024;

int fst_left[MaxN], fst_right[MaxN];
int num_left[MaxN];
int num_right[MaxN];
bool remaining[MaxN];
int answer[MaxN];

void Fail() {
  cout << "NO\n";
  exit(0);
}

int32_t main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout << fixed << setprecision(11);
  cerr << fixed << setprecision(6);

  int N;
  cin >> N;

  for (int i = 0; i < N; ++i) {
    cin >> num_left[i];
    fst_left[i] = num_left[i];
  }
  for (int i = 0; i < N; ++i) {
    cin >> num_right[i];
    fst_right[i] = num_right[i];
  }

  int rem = N;
  fill(remaining, remaining + N, true);

  int value = N;
  while (rem) {
    vector<int> zeros;
    for (int i = 0; i < N; ++i)
      if (remaining[i] && !num_left[i] && !num_right[i])
        zeros.PB(i);

    debug(zeros, rem);

    if (zeros.empty())
      Fail();

    for (int v : zeros) {
      answer[v] = value;
      remaining[v] = false;
    }

    for (int v : zeros) {
      for (int i = 0; i < N; ++i) {
        if (!remaining[i]) { continue; }
        debug(v, i);
        if (i < v)
          --num_right[i];
        else
          --num_left[i];
      }
      --rem;
    }
      --value;
  }

  for (int i = 0; i < N; ++i)
    if (num_left[i] != 0 || num_right[i] != 0)
      Fail();

  for (int i = 0; i < N; ++i)
    for (int j = i + 1; j < N; ++j) {
      if (answer[i] < answer[j]) {
        debug("iiii", i, j);
        --fst_right[i];
      }
      if (answer[i] > answer[j]) {
        debug("jjjj", i, j);
        --fst_left[j];
      }
    }

  for (int i = 0; i < N; ++i) {
    debug(i, fst_left[i], fst_right[i]);
    if (fst_left[i] || fst_right[i])
      Fail();
  }

  cout << "YES\n";
  for (int i = 0; i < N; ++i)
    cout << answer[i] << " ";
  cout << "\n";
}
